leagueDivisions.query:
query leagueDivisions($slug: String!, $session: Int) {
  league(slug: $slug) {
    id
    currentSessionId
    divisions(session: $session) {
      id
      name
      number
      format
      type
      nightOfPlay
      isMine
      session {
        id
        name
        __typename
      }
      __typename
    }
    __typename
  }
}

divisionLayout.query:
query divisionLayout($id: Int!) {
  division(id: $id) {
    id
    number
    name
    format
    isTournament
    type
    nightOfPlay
    timeOfPlay
    isMine
    state
    schedule {
      id
      __typename
    }
    league {
      id
      name
      __typename
    }
    session {
      id
      name
      __typename
    }
    tournament {
      id
      __typename
    }
    __typename
  }
}

DivisionContacts.query:
query DivisionContacts($id: Int!) {
  division(id: $id) {
    id
    name
    contacts {
      phone
      alias {
        id
        displayName
        __typename
      }
      __typename
    }
    __typename
  }
}

divsionStandings.query:
query divsionStandings($id: Int!) {
  division(id: $id) {
    id
    teams {
      id
      name
      number
      standing
      pointsLastWeek
      lastWeek
      sessionTotalPoints
      totalTeamMatchesPlayed
      isTied
      isBye
      league {
        id
        slug
        __typename
      }
      tournaments(time: FUTURE) {
        id
        tournamentTypeName
        __typename
      }
      __typename
    }
    __typename
  }
}

divisionRosters.query:
query divisionRosters($id: Int!) {
  division(id: $id) {
    id
    teams {
      isBye
      ...rosterComponent
      location {
        id
        name
        address {
          id
          name
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment rosterComponent on Team {
  id
  name
  number
  league {
    id
    slug
    __typename
  }
  division {
    id
    type
    __typename
  }
  roster {
    id
    memberNumber
    displayName
    matchesWon
    matchesPlayed
    ... on EightBallPlayer {
      pa
      ppm
      skillLevel
      __typename
    }
    ... on NineBallPlayer {
      pa
      ppm
      skillLevel
      __typename
    }
    member {
      id
      __typename
    }
    __typename
  }
  __typename
}

divisionSchedule.query:
query divisionSchedule($id: Int!) {
  viewer {
    id
    __typename
  }
  division(id: $id) {
    id
    contacts {
      phone
      alias {
        id
        displayName
        __typename
      }
      __typename
    }
    teams {
      id
      name
      active
      number
      isBye
      location {
        id
        name
        phone
        __typename
      }
      __typename
    }
    schedule {
      id
      description
      date
      weekOfPlay
      skip
      matches {
        ...matchListItem
        __typename
      }
      __typename
    }
    scheduleInEdit
    __typename
  }
}

fragment matchListItem on Match {
  id
  isBye
  status
  scoresheet
  startTime
  isMine
  isPaid
  isTournament
  isScored
  isFinalized
  isPlayoff
  description
  tableNumber
  results {
    homeAway
    points {
      total
      __typename
    }
    __typename
  }
  timeZone {
    id
    name
    __typename
  }
  location {
    id
    name
    address {
      id
      name
      __typename
    }
    __typename
  }
  home {
    id
    name
    number
    isMine
    __typename
  }
  away {
    id
    name
    number
    isMine
    __typename
  }
  league {
    id
    isMine
    slug
    isElectronicPaymentsEnabled
    __typename
  }
  orderItems {
    id
    order {
      id
      member {
        id
        firstName
        lastName
        __typename
      }
      __typename
    }
    __typename
  }
  division {
    id
    scheduleInEdit
    isTournament
    __typename
  }
  __typename
}
